import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify {public static void main(String[] args)throws Exception{int count=0;try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){if(!e.getName().endsWith(".class"))continue;ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);if(c.name.equals("dev/zomboid/mts/mixin/ManualMouseMixin")){if(c.invisibleAnnotations==null||c.invisibleAnnotations.stream().noneMatch(n->n.desc.equals("Lorg/spongepowered/asm/mixin/Mixin;")))throw new AssertionError("Mixin CLASS retention required");}
for(MethodNode m:c.methods){if(c.name.equals("minecrafttransportsimulator/items/instances/ItemItem")&&m.name.equals("doEntityInteraction"))for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof FieldInsnNode f&&f.name.equals("damageVar")&&i.getPrevious() instanceof VarInsnNode v&&v.var==1&&!f.owner.equals("minecrafttransportsimulator/entities/components/AEntityE_Interactable"))throw new AssertionError("Piece receiver requires base damageVar field owner");if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))!=0)continue;new Analyzer<>(new BasicVerifier()).analyze(c.name,m);count++;}}}System.out.println("Bytecode methods analyzed: "+count);}}
